mapper.select:
WHERE u.tenant_id = #{tenantId} AND u.id NOT IN (1, 3) AND u.status = 0 AND u.deleted = 0
AND (e.name LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR d.dept_name LIKE CONCAT('%', #{keyword}, '%'))
AND u.dept_id = #{deptId}
GROUP BY u.id, e.name, u.nickname, u.username, u.dept_id, d.dept_name ORDER BY COALESCE(d.sort, 999999), d.id, display_name, u.id LIMIT #{limit}
